  async function loadLiveState(){
    if(IS_FILE_PREVIEW){const live=previewMemory.live||emptyLiveState();engine.replaceState(live);return live;}
    try{
      const res=await apiFetch('/api/live/state'); if(!res.ok)throw new Error('Could not load live operational data.'); const live=await res.json();
      engine.replaceState(live||emptyLiveState());
      const available=[...new Set([...engine.state.calendar.map(x=>x.month),...engine.state.timeEntries.map(x=>x.month),...engine.state.payroll.map(x=>x.month)].filter(Boolean))].sort();
      if(available.length && !available.includes(state.month)) state.month=available[available.length-1];
      return live;
    }catch(err){console.warn(err);engine.replaceState(emptyLiveState());return emptyLiveState();}
  }
  function persistLocalLiveState(){previewMemory.live=JSON.parse(JSON.stringify(engine.state));queueStandaloneSave();}
  async function reloadLiveState(){await loadLiveState();await loadControlCenter();if(canUseRecoveryAssurance())await loadRecoveryAssurance(true);populateMonths();populateMtsMasters();renderControlDock();refreshCurrent();}

