  function switchView(view){
    if(view==='assistant'&&!developerStudioAllowed())return false;
    const target=$(`view-${view}`),m=meta[view];
    if(!target||!m)return false;
    state.view=view;
    document.body.classList.toggle('developer-jivan-view',view==='assistant'&&developerStudioAllowed());
    target.hidden=false;
    document.body.classList.toggle('company-view-active',view==='company');
    document.querySelectorAll('.view').forEach(x=>x.classList.remove('active-view'));
    target.classList.add('active-view');
    document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));
    $('pageEyebrow').textContent=m[0]; $('pageTitle').textContent=m[1]; $('pageSubtitle').textContent=m[2];
    $('sidebar').classList.remove('open'); refreshCurrent(); if(view==='assistant'&&developerStudioAllowed()){loadJivanStudio().then(()=>{renderJivanStudio();setDeveloperConsoleMode(state.jivanConsoleMode||'structure');renderJivanEngineStructure();}).catch(()=>{});} if(view==='assurance'||view==='audit')loadRecoveryAssurance().then(()=>refreshCurrent()).catch(()=>{}); if(view==='exceptions')loadRecoveryExceptionContext().then(()=>refreshCurrent()).catch(()=>{}); if(view==='health')loadSystemHealth(true).then(()=>renderSystemHealth()).catch(()=>{}); if(view==='recruiting'&&recruitmentHrAllowed())loadRecruitmentBundle(true).then(()=>{mergeRecruitmentNotificationsIntoControl();renderRecruiting();renderControlDock();}).catch(err=>toast(err.message));
    window.dispatchEvent(new CustomEvent('assurance-regent-view-change',{detail:agentPageContext()}));
    return true;
  }

