  /* v6.1 Scalability & Jivan resilience */
  function systemHealthAllowed(){const a=functionalAuthority(effectiveUserOrg(controlUser()||{}));return ['DEVELOPER','CEO','ADMINISTRATOR'].includes(a);}
  function healthStatusClass(status=''){const s=String(status||'').toUpperCase();return s==='HEALTHY'?'good':s==='ATTENTION'?'warn':'bad';}
  function bytesLabel(v=0){const n=Number(v||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;return `${(n/1048576).toFixed(1)} MB`;}
  async function loadSystemHealth(force=false){if(!browserSessionToken||!systemHealthAllowed())return null;if(!force&&state.systemHealth&&Date.now()-state.systemHealthLoadedAt<12000)return state.systemHealth;if(state.systemHealthBusy)return state.systemHealth;state.systemHealthBusy=true;try{const company=controlUser()?.role==='Developer'?(state.companyActiveId||''):currentCompanyId();const [health,incidents]=await Promise.all([supabaseRpc('assurance_regent_browser_scalability_health',{p_token:browserSessionToken,p_company_id:company},{bypassCache:force}),supabaseRpc('assurance_regent_browser_system_incident_list',{p_token:browserSessionToken,p_limit:60,p_company_id:company},{bypassCache:force})]);state.systemHealth=health||null;state.systemIncidents=Array.isArray(incidents)?incidents:[];state.systemHealthLoadedAt=Date.now();return health;}catch(err){console.warn('System health unavailable',err);return null;}finally{state.systemHealthBusy=false;}}
  async function runSafeSystemRecovery(action,automatic=false){if(!browserSessionToken)throw new Error('Sign in before using system recovery.');const a=String(action||'').toUpperCase(),company=controlUser()?.role==='Developer'?(state.companyActiveId||''):currentCompanyId();if(!['REQUEUE_STALE_TASKS','PURGE_EXPIRED_SESSIONS','PURGE_EXPIRED_RATE_BUCKETS'].includes(a))throw new Error('Unsupported recovery action.');const result=await supabaseRpc('assurance_regent_browser_system_recover',{p_token:browserSessionToken,p_action:a,p_company_id:company},{bypassCache:true});state.systemHealthLoadedAt=0;await loadSystemHealth(true);if(state.view==='health')renderSystemHealth();if(!automatic)toast(`Jivan recovery completed: ${Number(result?.affected||0)} item(s) repaired.`);return result;}
  function renderSystemHealth(){if(!systemHealthAllowed())return;const h=state.systemHealth||{},incidents=Array.isArray(state.systemIncidents)?state.systemIncidents:[];if($('systemHealthKpis'))$('systemHealthKpis').innerHTML=[['System status',h.status||'CHECKING','Current resilience state',healthStatusClass(h.status)],['Active sessions',h.activeSessions||0,'Concurrent signed-in sessions',''],['Queued tasks',h.queuedTasks||0,'Jivan delegated work',''],['Stale tasks',h.staleTasks||0,'Auto-recovery candidates',Number(h.staleTasks||0)?'bad':'good'],['Open incidents',h.openIncidents||0,'Recorded service/client faults',Number(h.highIncidents||0)?'bad':Number(h.openIncidents||0)?'warn':'good'],['State payload',bytesLabel(h.stateSizeBytes||0),'Legacy shared-state size',Number(h.stateSizeBytes||0)>8388608?'warn':'']].map(x=>`<article class="kpi-card ${x[3]}"><small>${esc(x[0])}</small><b>${esc(x[1])}</b><span>${esc(x[2])}</span></article>`).join('');if($('systemHealthSummary'))$('systemHealthSummary').innerHTML=`<div class="system-health-banner ${healthStatusClass(h.status)}"><div><b>${esc(h.status||'Checking system health…')}</b><span>Jivan resilience monitor · ${esc(h.generatedAt?new Date(h.generatedAt).toLocaleString():'waiting for health snapshot')}</span></div><div>${Number(h.staleTasks||0)?'<button class="btn small primary" id="healthRequeueStale" type="button">Repair stale tasks</button>':''}${controlUser()?.role==='Developer'?'<button class="btn small ghost" id="healthPurgeSessions" type="button">Clean expired sessions</button>':''}</div></div>`;if($('systemIncidentsBody'))$('systemIncidentsBody').innerHTML=incidents.length?incidents.map(i=>`<tr><td>${esc(String(i.last_seen_at||'').replace('T',' ').slice(0,19))}</td><td>${resultChip(i.severity||'WARNING')}</td><td><b>${esc(i.component||'')}</b><small>${esc(i.status||'')}</small></td><td class="wrap">${esc(i.message||'')}</td><td class="num">${esc(i.occurrence_count||1)}</td><td>${i.status==='OPEN'&&systemHealthAllowed()?`<button class="btn micro ghost" data-resolve-incident="${esc(i.id)}">Resolve</button>`:'—'}</td></tr>`).join(''):'<tr class="empty-row"><td colspan="6"><div class="table-empty"><b>No system incidents</b><span>Jivan has no unresolved reliability incidents in this scope.</span></div></td></tr>';paginateTable('systemIncidentsBody',true);$('healthRequeueStale')?.addEventListener('click',()=>runSafeSystemRecovery('REQUEUE_STALE_TASKS').catch(e=>toast(e.message)));$('healthPurgeSessions')?.addEventListener('click',()=>runSafeSystemRecovery('PURGE_EXPIRED_SESSIONS').catch(e=>toast(e.message)));document.querySelectorAll('[data-resolve-incident]').forEach(b=>b.addEventListener('click',async()=>{try{await supabaseRpc('assurance_regent_browser_system_incident_resolve',{p_token:browserSessionToken,p_incident_id:Number(b.dataset.resolveIncident),p_resolution:'Reviewed and resolved from System Health.'},{bypassCache:true});await loadSystemHealth(true);renderSystemHealth();}catch(err){toast(err.message);}}));}
  function startResilienceMonitor(){const tick=async()=>{if(document.hidden||!browserSessionToken||!systemHealthAllowed()||!isClientLeader())return;const h=await loadSystemHealth(true);if(!h)return;const now=Date.now();if(Number(h.staleTasks||0)>0&&now-state.lastAutoRecoveryAt>120000){state.lastAutoRecoveryAt=now;try{const r=await runSafeSystemRecovery('REQUEUE_STALE_TASKS',true);if(Number(r?.affected||0)>0){toast(`Jivan automatically recovered ${r.affected} stale background task(s).`);await agentGovernanceAudit('system_recovery','REQUEUE_STALE_TASKS','OK',`Jivan resilience automatically requeued ${r.affected} stale task(s).`,{automatic:true});}}catch(err){console.warn('Jivan automatic recovery could not complete',err);}}};setTimeout(()=>tick().catch(()=>{}),3500);setInterval(()=>tick().catch(()=>{}),60000+Math.floor(Math.random()*15000));}
  function bindSystemHealth(){$('systemHealthRefresh')?.addEventListener('click',async()=>{await loadSystemHealth(true);renderSystemHealth();toast('System health refreshed.');});$('systemHealthRunSafeRecovery')?.addEventListener('click',async()=>{try{const h=await loadSystemHealth(true),actions=Array.isArray(h?.recommendedSafeActions)?h.recommendedSafeActions:[];let affected=0;for(const a of actions.filter(x=>x==='REQUEUE_STALE_TASKS')){const r=await runSafeSystemRecovery(a,true);affected+=Number(r?.affected||0);}await loadSystemHealth(true);renderSystemHealth();toast(affected?`Jivan repaired ${affected} recoverable item(s).`:'No safe automatic recovery was needed.');}catch(err){toast(err.message);}});}

  /* Leave & Work Status v5.8 */
  /* v6.2 Developer Jivan Studio */
  function developerStudioAllowed(){return String(controlUser()?.role||'')==='Developer';}
  function defaultJivanStudioConfig(){return {identity:{displayName:'Jivan',persona:'Calm, concise, technically capable operations intelligence for Assurance Regent. Respond naturally to the user’s actual instruction, carry out permitted tasks first, and explain only what is relevant.'},runtime:{reasoningProfile:'ADVANCED_BALANCED',autonomy:'GUARDED_ADVANCED',maxToolSteps:20,specialistRouting:true,routingMode:'AUTO',backgroundDelegation:true,autoDiagnostics:true},rules:{additionalRules:'',allowMessageDrafting:true,allowExternalEmail:false,allowExternalWhatsApp:false,allowExternalCalls:false,requireExplicitSendConfirmation:true},agents:[{id:'systems-engineer',name:'Systems Engineer',enabled:true,domains:['system','error','performance','scalability','database','edge function','maintenance'],instructions:'Diagnose Assurance Regent reliability, performance, integration and deployment problems. Recommend bounded repairs; never weaken security controls.'},{id:'communications',name:'Communications Agent',enabled:true,domains:['email','whatsapp','message','call','communication','contact'],instructions:'Draft professional external communications. Preserve recipient intent, privacy and consent requirements. Sending remains explicitly confirmed.'},{id:'recovery-finance',name:'Recovery & Finance Agent',enabled:true,domains:['recovery','finance','payroll','journal','donor','budget','voucher'],instructions:'Assist with Recovery Assurance, financial analysis and accounting drafts while preserving human approval boundaries.'},{id:'people-hr',name:'People & HR Agent',enabled:true,domains:['employee','leave','hr','recruitment','onboarding','people'],instructions:'Assist with HR operations within role and company boundaries. Do not make unauthorized employment decisions.'},{id:'research-analytics',name:'Research & Analytics Agent',enabled:true,domains:['research','analyze','analytics','report','forecast','visualization'],instructions:'Perform evidence-grounded research, quantitative analysis and reporting. Clearly distinguish facts, calculations and inference.'},{id:'projects-programs',name:'Projects & Programs Agent',enabled:true,domains:['project','program','programme','portfolio','activity','workplan'],instructions:'Assist with project/program oversight, delivery analysis and managed-team workflows within authorization boundaries.'}],connectors:{email:{provider:'RESEND',enabled:false,fromAddress:'',secretAlias:'RESEND_API_KEY'},whatsapp:{provider:'TWILIO',enabled:false,fromNumber:'',secretAlias:'TWILIO_AUTH_TOKEN'},voice:{provider:'TWILIO',enabled:false,fromNumber:'',secretAlias:'TWILIO_AUTH_TOKEN'}},maintenance:{autoRequeueStaleTasks:true,incidentDiagnostics:true,cacheSelfRepair:true,allowAutomaticCodeChanges:false,allowAutomaticSecurityChanges:false},visual:{hologramEnabled:false,motionLevel:'NONE'}};}
  function jivanStudioConfig(){return state.jivanStudio?.active?.config||defaultJivanStudioConfig();}
  function studioAgentRows(){return Array.isArray(jivanStudioConfig()?.agents)?jivanStudioConfig().agents:[];}
  async function loadJivanStudio(force=false){if(!developerStudioAllowed()||!browserSessionToken)return null;if(!force&&state.jivanStudio&&Date.now()-state.jivanStudioLoadedAt<4500)return state.jivanStudio;try{const [bundle,status,health]=await Promise.all([supabaseRpc('assurance_regent_browser_jivan_studio_get',{p_token:browserSessionToken},{bypassCache:force}),supabaseFunction('recovery-agent',{mode:'studio_status'}).catch(()=>null),loadSystemHealth(force).catch(()=>null)]);state.jivanStudio=bundle||null;state.jivanStudioConnectorStatus=status?.studio_connectors||null;state.jivanStudioLoadedAt=Date.now();if(health)state.systemHealth=health;return bundle;}catch(err){console.warn('Jivan Studio unavailable',err);return null;}}
  function setJivanStudioTab(tab='builder'){state.jivanStudioTab=tab;document.querySelectorAll('[data-studio-tab]').forEach(b=>b.classList.toggle('active',b.dataset.studioTab===tab));document.querySelectorAll('[data-studio-pane]').forEach(p=>{p.hidden=p.dataset.studioPane!==tab;p.classList.toggle('active',p.dataset.studioPane===tab);});}
