  function normalizeDecisionTree(value,fallback=[]){const rows=Array.isArray(value)?value:[];const clean=rows.map(x=>{if(typeof x==='string'){const p=x.split('|');return {title:String(p.shift()||'Stage').trim(),instruction:p.join('|').trim()};}return {title:String(x?.title||x?.stage||'Stage').trim(),instruction:String(x?.instruction||x?.rule||x?.detail||'').trim()};}).filter(x=>x.title||x.instruction).slice(0,12);return clean.length?clean:fallback;}
  function decisionTreeToText(value,fallback=[]){return normalizeDecisionTree(value,fallback).map(x=>`${x.title} | ${x.instruction}`).join('\n');}
