    const financeDashboard=['DEVELOPER','CEO','ADMINISTRATOR','FINANCE_MANAGER'].includes(functionalAuthority(effectiveUserOrg(controlUser()||{})));financeDashboard?(payroll.length?drawHorizontalBars($('salaryBandChart'),bands.map(x=>x.label),bands.map(x=>payroll.filter(p=>Number(p.allocableCost)>=x.min&&Number(p.allocableCost)<x.max).length),'#1cb7c9'):drawEmptyChart($('salaryBandChart'),'Waiting for live payroll data')):drawEmptyChart($('salaryBandChart'),'Finance / Executive access only');
    if(!d.monthly.length){['costChart','hoursChart','readinessChart','projectChart'].forEach(id=>drawEmptyChart($(id),'Waiting for live data'));return;}
