  /* Company — live organization directory and structure */
  function companyInitials(name){return String(name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'?';}
  function companyById(id){return (previewAuthData().companies||[]).find(c=>c.id===id)||null;}
  function employeeRecord(employeeId='',name=''){const id=String(employeeId||'').trim(),n=String(name||'').trim().toLowerCase();return engine.state.employees.find(e=>id&&e.employeeId===id)||engine.state.employees.find(e=>n&&String(e.name||'').trim().toLowerCase()===n)||null;}
  function safeProfilePhoto(value){const v=String(value||'').trim();return /^data:image\/(?:png|jpeg|jpg|webp|gif);base64,/i.test(v)?v:'';}
  function userAvatar(employeeId='',name='',size='sm',extra=''){const e=typeof employeeId==='object'&&employeeId?employeeId:employeeRecord(employeeId,name);const label=e?.name||name||e?.employeeId||employeeId||'User',photo=safeProfilePhoto(e?.profilePhoto);return `<span class=\"user-avatar ${esc(size)} ${esc(extra)}\" title=\"${esc(label)}\">${photo?`<img src=\"${esc(photo)}\" alt=\"${esc(label)}\" />`:esc(companyInitials(label))}</span>`;}
  function userIdentity(employeeId='',name='',subtitle='',size='sm'){const e=typeof employeeId==='object'&&employeeId?employeeId:employeeRecord(employeeId,name);const label=e?.name||name||e?.employeeId||employeeId||'Unassigned user';const sub=subtitle||e?.position||e?.employeeId||'';return `<span class=\"user-identity\">${userAvatar(e||employeeId,label,size)}<span class=\"user-identity-text\"><b>${esc(label)}</b>${sub?`<small>${esc(sub)}</small>`:''}</span></span>`;}
  function rawCell(html){return {__html:String(html||'')};}
  function setProfilePreview(id,data,name=''){const el=$(id);if(!el)return;const photo=safeProfilePhoto(data);el.innerHTML=photo?`<img src=\"${esc(photo)}\" alt=\"${esc(name||'Profile picture preview')}\" />`:`<span>${esc(companyInitials(name||'Photo'))}</span>`;}
  function imageFileLooksLike(file){const n=String(file?.name||'').toLowerCase();return /^image\//i.test(file?.type||'')||/\.(?:jpe?g|jfif|png|gif|webp|bmp|tiff?|heic|heif|avif|ico)$/i.test(n);}
