  async function copyRecruitmentLink(url,label='Link'){try{await navigator.clipboard.writeText(url);toast(`${label} copied.`);}catch{const t=document.createElement('textarea');t.value=url;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();toast(`${label} copied.`);}}
  function recruitmentSharePayload(id){
    const v=engine.state.vacancies.find(x=>String(x.id)===String(id));
    if(!v?.publicVisible||v?.archived)return null;
    const url=recruitmentPublicUrl(id),company=activeCompanyForView()?.name||currentCompanyId()||'Organization';
    const parts=[`We are hiring: ${v.title}`,v.location?`Location: ${v.location}`:'',v.employmentType?`Type: ${v.employmentType}`:'',v.experienceYears!==''&&v.experienceYears!=null?`Experience: ${v.experienceYears}+ years`:'',v.closeDate?`Apply by: ${v.closeDate}`:'','View the full vacancy and apply:'];
    return {vacancy:v,url,company,text:parts.filter(Boolean).join('\n'),title:`${v.title} — ${company}`};
  }
  function openVacancyShareDialog(id){
    const payload=recruitmentSharePayload(id);if(!payload)return toast('Publish this active vacancy externally before sharing it.');
    $('recruitShareVacancyId').value=payload.vacancy.id;$('recruitShareTitle').textContent=payload.vacancy.title;$('recruitShareMeta').textContent=[payload.company,payload.vacancy.location,payload.vacancy.closeDate?`Deadline ${payload.vacancy.closeDate}`:''].filter(Boolean).join(' · ');$('recruitShareLink').value=payload.url;$('recruitShareText').value=`${payload.text}\n${payload.url}`;$('recruitShareDialog')?.showModal();
  }
  async function sharePublicVacancy(id,platform){
    const payload=recruitmentSharePayload(id);if(!payload)return toast('Publish this active vacancy externally before sharing it.');
    const fullText=`${payload.text}\n${payload.url}`;
    if(platform==='copy')return copyRecruitmentLink(payload.url,'Public vacancy link');
    if(platform==='copy-post')return copyRecruitmentLink(fullText,'Vacancy post');
    if(platform==='native'){
      if(navigator.share){try{await navigator.share({title:payload.title,text:payload.text,url:payload.url});return;}catch(err){if(err?.name==='AbortError')return;}}
      return copyRecruitmentLink(fullText,'Vacancy post');
    }
    const e=encodeURIComponent,url=payload.url;
    const targets={
      facebook:`https://www.facebook.com/sharer/sharer.php?u=${e(url)}`,
      whatsapp:`https://wa.me/?text=${e(fullText)}`,
      x:`https://twitter.com/intent/tweet?text=${e(payload.text)}&url=${e(url)}`,
      linkedin:`https://www.linkedin.com/sharing/share-offsite/?url=${e(url)}`
    };
    const target=targets[platform];if(!target)return;
    const w=window.open(target,'_blank','noopener,noreferrer');if(w)try{w.opener=null;}catch{}else toast('Allow pop-ups to open the selected social platform.');
  }
  function copyPublicVacancyLink(id){return sharePublicVacancy(id,'copy');}
