  async function importRecruitApplication(id){const app=(recruitmentBundle().applications||[]).find(x=>String(x.id)===String(id));if(!app)return;try{const v=engine.state.vacancies.find(x=>String(x.id)===String(app.vacancy_id));const c=engine.upsertCandidate({companyId:app.company_id,name:app.applicant_name,email:app.email,phone:app.phone,vacancyId:app.vacancy_id,jobTitle:app.vacancy_title||v?.title||'',department:v?.department||'',location:app.location||v?.location||'',employmentType:v?.employmentType||'Full Time',stage:'Applied',status:'Active',appliedDate:String(app.applied_at||'').slice(0,10),notes:[app.cover_note,'Imported from external careers application.'].filter(Boolean).join('\n\n')});persistLocalLiveState();await supabaseRpc('assurance_regent_browser_recruitment_application_imported',{p_token:browserSessionToken,p_application_id:id,p_candidate_id:c.id},{bypassCache:true});await reloadLiveState();await loadRecruitmentBundle(true);state.recruitTab='candidates';renderRecruiting();await refreshControlCenter();toast('External applicant imported into the candidate pipeline.');}catch(err){toast(err.message);}}
  function openRecruitInterviewDialog(id){const meet=normalizeGoogleMeetUrl(recruitmentBundle().meetUrl||companyInterviewMeetUrl());if(!meet)return toast('This company has no Google Meet interview room. Ask the Developer to configure it in Company service directory.');const app=(recruitmentBundle().applications||[]).find(x=>String(x.id)===String(id));if(!app)return;if($('recruitInterviewApplicationId'))$('recruitInterviewApplicationId').value=app.id;if($('recruitInterviewSummary'))$('recruitInterviewSummary').innerHTML=`<b>${esc(app.applicant_name)}</b><span>${esc(app.vacancy_title)} · ${esc(app.email)}</span>`;if($('recruitInterviewNotes'))$('recruitInterviewNotes').value='';if($('recruitInterviewDate')){const d=new Date(Date.now()+86400000);d.setMinutes(Math.ceil(d.getMinutes()/15)*15,0,0);$('recruitInterviewDate').value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}$('recruitInterviewDialog')?.showModal();}
  async function saveRecruitInterviewSchedule(e){e.preventDefault();const meet=normalizeGoogleMeetUrl(recruitmentBundle().meetUrl||companyInterviewMeetUrl());if(!meet)return toast('The Developer must configure this company’s Google Meet interview room before an interview can be scheduled.');const id=$('recruitInterviewApplicationId')?.value||'',raw=$('recruitInterviewDate')?.value||'';if(!id||!raw)return toast('Choose an application and interview time.');try{const when=new Date(raw);if(Number.isNaN(when.getTime()))throw new Error('Enter a valid interview date and time.');const row=await supabaseRpc('assurance_regent_browser_recruitment_interview_schedule',{p_token:browserSessionToken,p_application_id:id,p_scheduled_at:when.toISOString(),p_time_zone:$('recruitInterviewTimezone')?.value||'Africa/Lusaka',p_notes:$('recruitInterviewNotes')?.value.trim()||''},{bypassCache:true});$('recruitInterviewDialog')?.close();await loadRecruitmentBundle(true);state.recruitTab='interviews';renderRecruiting();await refreshControlCenter();await copyRecruitmentLink(recruitmentInterviewUrl(row.candidate_token),'Candidate interview invitation');toast('Interview scheduled. Candidate invitation copied; HR can also enter the room from the Interviews tab.');setTimeout(()=>openRecruitOutreach(id),180);}catch(err){toast(err.message);}}
