  async function runRecruitAiFitReview(){if(!recruitmentHrAllowed())return toast('Human Resources recruitment authority is required.');const vacancyId=state.recruitVacancy||'';if(!vacancyId)return toast('Select one vacancy first so AI can compare applicants against the same job criteria.');const btn=$('recruitAiRank');try{if(btn)btn.disabled=true;toast('Jivan is reviewing job-related applicant fit. HR remains the decision maker.');await supabaseFunction('recruitment-public',{action:'hr_rank_candidates',vacancy_id:vacancyId});await loadRecruitmentBundle(true);renderRecruiting();toast('AI fit review complete. Scores are advisory; review the evidence before shortlisting.');}catch(err){toast(err.message);}finally{if(btn)btn.disabled=false;}}
