  async function openRecruitOutreach(id){const a=(recruitmentBundle().applications||[]).find(x=>String(x.id)===String(id));if(!a)return;const interview=interviewForApplication(id),url=interview?recruitmentInterviewUrl(interview.candidate_token):'';if($('recruitOutreachApplicationId'))$('recruitOutreachApplicationId').value=a.id;if($('recruitOutreachRecipient'))$('recruitOutreachRecipient').innerHTML=`<b>${esc(a.applicant_name)} · ${esc(a.vacancy_title)}</b>Email: ${esc(a.email||'Not supplied')} · WhatsApp/phone: ${esc(a.phone||'Not supplied')}${interview?`<br>Interview: ${esc(new Date(interview.scheduled_at).toLocaleString())} · ${esc(interview.time_zone||'')}`:'<br>No interview time has been scheduled yet.'}`;try{const prepared=await supabaseFunction('recruitment-public',{action:'hr_prepare_outreach',application_id:id,interview_url:url});$('recruitOutreachSubject').value=prepared.subject||`Interview invitation — ${a.vacancy_title}`;$('recruitOutreachMessage').value=prepared.message||'';$('recruitOutreachDialog')?.showModal();}catch(err){toast(err.message);}}
