    const panels={vacancies:'recruitPanelVacancies',applications:'recruitPanelApplications',candidates:'recruitPanelCandidates',interviews:'recruitPanelInterviews',funnel:'recruitPanelFunnel',analytics:'recruitPanelAnalytics'};Object.values(panels).forEach(id=>$(id)?.classList.remove('active'));$(panels[state.recruitTab]||panels.funnel)?.classList.add('active');
    const filter=$('recruitVacancyFilter'),current=state.recruitVacancy;filter.innerHTML='<option value="">All vacancies</option>'+vacancies.map(v=>`<option value="${esc(v.id)}">${esc(v.title)}</option>`).join('');if([...filter.options].some(o=>o.value===current))filter.value=current;else state.recruitVacancy='';
