  function renderRecruitInterviews(){const table=$('recruitInterviewsTable');if(!table)return;let rows=newestFirst(recruitmentBundle().interviews||[],['scheduled_at','created_at']);if(state.recruitVacancy)rows=rows.filter(i=>i.vacancy_id===state.recruitVacancy);const html=rows.length?rows.map(i=>`<tr><td><b>${esc(i.candidate_name)}</b><small class="table-subline">${esc(i.candidate_email||'')}</small></td><td>${esc(i.vacancy_title||'')}</td><td><b>${esc(new Date(i.scheduled_at).toLocaleString())}</b><small class="table-subline">${esc(i.time_zone||'Africa/Lusaka')}</small></td><td>${directoryStatusChip(i.status)}</td><td class="recruit-row-actions"><button class="btn micro ghost" type="button" data-interview-action="invite" data-interview-id="${encodeURIComponent(i.id)}" data-interview-token="${encodeURIComponent(i.candidate_token)}">Copy invite</button><button class="btn micro primary" type="button" data-interview-action="room" data-interview-id="${encodeURIComponent(i.id)}" ${normalizeGoogleMeetUrl(i.meet_url)?'':'disabled title="Developer interview-room setup required"'}>Enter room</button>${i.status==='SCHEDULED'?`<button class="btn micro ghost" type="button" data-interview-action="complete" data-interview-id="${encodeURIComponent(i.id)}">Complete</button><button class="btn micro ghost danger-outline" type="button" data-interview-action="cancel" data-interview-id="${encodeURIComponent(i.id)}">Cancel</button>`:''}</td></tr>`).join(''):'<tr class="empty-row"><td colspan="5"><div class="table-empty"><b>No interviews scheduled</b><span>Open an external application and choose Interview to create a candidate invitation.</span></div></td></tr>';table.innerHTML=`<thead><tr><th>Candidate</th><th>Vacancy</th><th>Scheduled</th><th>Status</th><th>Interview controls</th></tr></thead><tbody>${html}</tbody>`;paginateTable('recruitInterviewsTable',true);}
