    const res=await apiFetch('/api/live/onboarding',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({onboarding_id:row.id,candidate_id:row.candidateId,employee_id:row.employeeId,employee_name:row.name,job_title:row.jobTitle,department:row.department,location:row.location,employment_type:row.employmentType,hire_date:row.hireDate,profile_photo:row.profilePhoto,step:row.step,status:row.status,checklist:row.checklist||{}})});const body=await res.json();if(!res.ok)throw new Error(body.error||'Could not update onboarding.');return body;
