  function recoveryAuditTests(){const month=String(state.month||''),rows=recoveryComputedPassports(),entries=(engine.state.timeEntries||[]).filter(e=>String(e.month||'')===month),analyzed=engine.analyzedTimeEntries().filter(e=>String(e.month||'')===month),payroll=engine.payrollAnalysis().filter(x=>String(x.month||'')===month),checks=engine.checks(),monthChecks=(checks.rows||[]).filter(x=>String(x.month||'')===month),b=recoveryBundle(),tests=[];const add=(name,scope,exceptions,risk,action)=>tests.push({name,scope,result:exceptions?'FAIL':'PASS',exceptions,risk,action});const dup=new Map();for(const e of entries){const k=[e.employeeId,e.date,e.projectCode,String(e.activity||'').toLowerCase(),e.hours].join('|');dup.set(k,(dup.get(k)||0)+1);}add('Duplicate time evidence','Recovery Time Entry',[...dup.values()].filter(x=>x>1).length,'HIGH','Investigate duplicate work evidence before approval.');add('Time-entry bounds','Recovery Time Entry',entries.filter(e=>Number(e.hours)<=0||Number(e.hours)>24||Math.abs(Number(e.hours)*4-Math.round(Number(e.hours)*4))>1e-8).length,'HIGH','Correct impossible or non-quarter-hour entries.');add('Project eligibility','Employee × project',analyzed.filter(e=>e.projectEligibility==='BLOCK').length,'HIGH','Correct project/date/employee eligibility; never override donor restrictions.');add('Approval completeness','Monthly time evidence',entries.filter(e=>String(e.status||'').toLowerCase()!=='finance approved'&&String(e.status||'').toLowerCase()!=='approved').length,'HIGH','Complete the human approval chain.');add('Payroll configuration','Payroll',payroll.filter(x=>String(x.configurationStatus||'').toUpperCase()==='REVIEW').length,'HIGH','Configure benefits, statutory costs and exclusions before recovery.');add('Source reconciliation','Checks',monthChecks.filter(x=>x.result==='FAIL').length,'HIGH','Reconcile calculated hours to source timesheet totals.');add('Five-key Recovery Gate','Recovery Passport',rows.filter(x=>x.finalStatus==='BLOCKED').length,'HIGH','Use counterfactual recovery advice to clear each failed key.');add('Supporting evidence rules','Recovery Passport',rows.filter(x=>x.keys?.evidence!=='PASS').length,'MEDIUM','Link required supporting documents to the employee-project period.');add('Project personnel budget','Project budget',rows.filter(x=>x.keys?.budget!=='PASS').length,'HIGH','Resolve aggregate donor/project personnel-budget exceptions.');const periodPassports=(b.passports||[]).filter(x=>String(x.reporting_month||'').slice(0,10)===month);const badHashes=periodPassports.filter(x=>!x.payload_hash||!x.source_state_hash).length;add('Immutable snapshot hashes','Passport archive',badHashes,'HIGH','All immutable snapshots must retain payload and source-state hashes.');let sod=0;for(const p of periodPassports){const a=recoveryLatestApproval(p.id,'FINANCE_ASSURANCE');if(a&&String(a.actor_id)===String(p.created_by))sod++;}add('Segregation of duties','Passport certification',sod,'MEDIUM','Where policy requires separation, have a different Finance reviewer certify the prepared Passport.');const periodIds=new Set(periodPassports.map(x=>String(x.id))),periodJournals=(b.journals||[]).filter(j=>periodIds.has(String(j.passport_id)));let unbalanced=0;for(const j of periodJournals){const lines=(b.journalLines||[]).filter(x=>String(x.batch_id)===String(j.id)),debit=lines.reduce((a,x)=>a+Number(x.debit||0),0),credit=lines.reduce((a,x)=>a+Number(x.credit||0),0);if(Math.abs(debit-credit)>.01)unbalanced++;}add('Journal balance','Accounting handoff',unbalanced,'HIGH','Every journal batch must balance debit to credit before export.');return tests;}
  async function renderRecoveryAudit(){if(!canUseRecoveryAssurance())return;await loadRecoveryAssurance();const tests=state.recoveryAuditTests?.length?state.recoveryAuditTests:recoveryAuditTests(),fails=tests.filter(x=>x.result==='FAIL'),high=fails.filter(x=>x.risk==='HIGH').length;if($('recoveryAuditKpis'))$('recoveryAuditKpis').innerHTML=[['Tests',tests.length,'Deterministic controls',''],['Failed',fails.length,'Exceptions requiring action',fails.length?'bad':'good'],['High risk',high,'Priority audit findings',high?'bad':'good'],['Audit events',(recoveryBundle().audit||[]).length,'Append-only evidence','']].map(x=>`<article class="kpi-card ${x[3]}"><small>${esc(x[0])}</small><b>${esc(x[1])}</b><span>${esc(x[2])}</span></article>`).join('');if($('recoveryAuditTestsBody'))$('recoveryAuditTestsBody').innerHTML=tests.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.scope)}</td><td>${resultChip(t.result)}</td><td class="num">${esc(t.exceptions)}</td><td><span class="recovery-test-risk ${t.risk.toLowerCase()}">${esc(t.risk)}</span></td><td>${esc(t.action)}</td></tr>`).join('');paginateTable('recoveryAuditTestsBody',true);const events=newestFirst(recoveryBundle().audit||[],['created_at']);if($('recoveryAuditEventsBody'))$('recoveryAuditEventsBody').innerHTML=events.length?events.map(a=>`<tr><td>${esc(String(a.created_at||'').replace('T',' ').slice(0,19))}</td><td>${esc(a.actor_id||'')}</td><td>${esc(a.authority||'')}</td><td>${esc(a.event_type||'')}</td><td>${esc(a.ref_type||'')}<small>${esc(a.ref_id||'')}</small></td><td>${esc(a.action||'')}</td><td>${resultChip(a.status||'OK')}</td><td class="wrap">${esc(JSON.stringify(a.detail||{}).slice(0,300))}</td></tr>`).join(''):'<tr class="empty-row"><td colspan="8"><div class="table-empty"><b>No recovery audit events yet</b><span>Create a Passport snapshot, link evidence, approve assurance, or run tests to build the trail.</span></div></td></tr>';paginateTable('recoveryAuditEventsBody',true);}
  async function runRecoveryAuditTests(){state.recoveryAuditTests=recoveryAuditTests();const fails=state.recoveryAuditTests.filter(x=>x.result==='FAIL').length;try{await supabaseRpc('assurance_regent_browser_recovery_audit_append',{p_token:browserSessionToken,p_company_id:recoveryCompanyId(),p_event_type:'AUDIT_TEST',p_ref_type:'RECOVERY_PERIOD',p_ref_id:state.month,p_action:'RUN_CONTROL_TESTS',p_status:fails?'REVIEW':'PASS',p_detail:{tests:state.recoveryAuditTests.length,failed:fails,highRisk:state.recoveryAuditTests.filter(x=>x.result==='FAIL'&&x.risk==='HIGH').length}});}catch(err){console.warn('Audit event could not be persisted',err);}state.recoveryLoadedAt=0;await loadRecoveryAssurance(true);await renderRecoveryAudit();toast(fails?`${fails} recovery audit test(s) require attention.`:'All recovery audit tests passed.');}
