  const TABLE_PAGE_SIZE=10;
  function renderSimpleTable(id,headers,rows){const cell=v=>v&&typeof v==='object'&&Object.prototype.hasOwnProperty.call(v,'__html')?v.__html:esc(v??'');const body=rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${cell(v)}</td>`).join('')}</tr>`).join(''):`<tr class="empty-row"><td colspan="${headers.length}"><div class="table-empty"><b>No live records yet</b><span>Use the capture form or Work Activity Hub to add data.</span></div></td></tr>`;$(id).innerHTML=`<thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body}</tbody>`;paginateTable(id,true);}
  function paginationNumbers(total,current){
    if(total<=7)return Array.from({length:total},(_,i)=>i+1);
    if(current<=4)return [1,2,3,4,5,'…',total];
    if(current>=total-3)return [1,'…',total-4,total-3,total-2,total-1,total];
    return [1,'…',current-1,current,current+1,'…',total];
  }
  function paginateTable(targetId,reset=false){
    const target=$(targetId);if(!target)return;const table=target.tagName==='TABLE'?target:target.closest('table');if(!table||!table.tBodies.length)return;
    const body=table.tBodies[0],allRows=[...body.rows],rows=allRows.filter(row=>!row.classList.contains('empty-row')),wrap=table.closest('.table-wrap');if(!wrap)return;
    let pager=wrap.nextElementSibling;
    if(!pager||!pager.classList.contains('table-pager')||pager.dataset.for!==targetId){pager=document.createElement('div');pager.className='table-pager';pager.dataset.for=targetId;wrap.insertAdjacentElement('afterend',pager);}
    if(reset||!pager.dataset.page)pager.dataset.page='1';
    const totalRows=rows.length;if(totalRows===0){pager.innerHTML='';pager.hidden=true;allRows.forEach(row=>row.hidden=false);return;}pager.hidden=false;const totalPages=Math.max(1,Math.ceil(totalRows/TABLE_PAGE_SIZE));let page=Math.max(1,Math.min(totalPages,Number(pager.dataset.page)||1));pager.dataset.page=String(page);
    const draw=next=>{page=Math.max(1,Math.min(totalPages,next));pager.dataset.page=String(page);const start=(page-1)*TABLE_PAGE_SIZE,end=start+TABLE_PAGE_SIZE;rows.forEach((row,i)=>{row.hidden=i<start||i>=end;});const first=totalRows?start+1:0,last=Math.min(end,totalRows),numbers=paginationNumbers(totalPages,page);pager.innerHTML=`<span class="pager-summary">Rows ${first}–${last} of ${totalRows}</span><div class="pager-controls"><button type="button" class="pager-button pager-arrow" data-page="${page-1}" ${page<=1?'disabled':''} aria-label="Previous page">←</button><div class="pager-pages">${numbers.map(n=>n==='…'?'<span class="pager-ellipsis">…</span>':`<button type="button" class="pager-button ${n===page?'active':''}" data-page="${n}" aria-label="Page ${n}" ${n===page?'aria-current="page"':''}>${n}</button>`).join('')}</div><button type="button" class="pager-button pager-arrow" data-page="${page+1}" ${page>=totalPages?'disabled':''} aria-label="Next page">→</button></div>`;pager.querySelectorAll('[data-page]').forEach(btn=>btn.addEventListener('click',()=>draw(Number(btn.dataset.page))));};
    draw(page);
  }

  function bindScenario(){
    $('newTimeBtn')?.addEventListener('click',()=>{
      if(!engine.state.employees.length||!engine.state.projects.length)return toast('Add an employee and project first, or create them through Work Activity Hub.');
      $('scenarioDate').value=state.month.slice(0,7)+'-15'; $('scenarioStatus').value='Draft'; $('timeDialog').showModal();
    });
    $('saveScenario').addEventListener('click',async e=>{
      e.preventDefault();
      const input={date:$('scenarioDate').value,employee_id:$('scenarioEmployee').value,project_code:$('scenarioProject').value,hours:Number($('scenarioHours').value),activity:$('scenarioActivity').value,status:$('scenarioStatus').value};
      try{
        if(STANDALONE_MODE){engine.addTimeEntry({companyId:currentCompanyId(),date:input.date,projectCode:input.project_code,hours:input.hours,activity:input.activity,status:input.status,employeeId:input.employee_id,aiSuggestedProject:input.project_code,employeeDecision:'Accepted'});persistLocalLiveState();}
        else {const res=await apiFetch('/api/live/time',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)});const body=await res.json();if(!res.ok)throw new Error(body.error||'Could not save live time entry.');}
        $('timeDialog').close();toast('Live time entry saved and connected calculations refreshed.');await reloadLiveState();
      }catch(err){toast(err.message);}
    });
  }

