  function populateMtsMasters(){
    if(!$('mtsEmployee'))return;
    if($('mtsEmployeeIds')) $('mtsEmployeeIds').innerHTML=engine.state.employees.map(e=>`<option value="${esc(e.employeeId)}">${esc(e.name)}${e.position?` · ${esc(e.position)}`:''}</option>`).join('');
    if($('mtsProjectCodes')) $('mtsProjectCodes').innerHTML=engine.state.projects.filter(p=>p.status==='Active').map(p=>`<option value="${esc(p.code)}">${esc(p.name||p.code)}${p.donor?` · ${esc(p.donor)}`:''}</option>`).join('');
    const sessionMonths=state.mtsSessions.map(x=>String(x.work_date||'').slice(0,7)).filter(Boolean);
    const monthValues=[...new Set([...engine.state.calendar.map(x=>x.month?.slice(0,7)),...sessionMonths].filter(Boolean))].sort();
    $('mtsMonthFilter').innerHTML='<option value="">All months</option>'+monthValues.map(m=>`<option value="${m}">${window.ADRAEngine.monthLabel(m+'-01')}</option>`).join('');
    const years=[...new Set([...engine.state.calendar.map(x=>String(x.date||'').slice(0,4)),...state.mtsSessions.map(x=>String(x.work_date||'').slice(0,4))].filter(Boolean))].sort();
    $('mtsYearFilter').innerHTML='<option value="">All years</option>'+years.map(y=>`<option>${y}</option>`).join('');
  }
  function progressBand(value){const v=Math.max(0,Math.min(100,Number(value||0)));if(v>=100)return {className:'progress-complete',labelClass:'complete',label:'Complete'};if(v>=80)return {className:'progress-near',labelClass:'near',label:'Near completion'};if(v>=50)return {className:'progress-moderate',labelClass:'moderate',label:'Moderate'};return {className:'progress-incomplete',labelClass:'incomplete',label:'Incomplete'};}
  function elapsedTaskDays(row){const start=new Date(row?.created_at||row?.clock_in_at||0),end=new Date(row?.status==='completed'?(row.clock_out_at||row.updated_at||Date.now()):Date.now());if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime()))return 0;return Math.max(1,Math.ceil((end-start)/86400000));}
  function localMtsStore(){return previewMemory.mts;}
  function saveLocalMtsStore(v){previewMemory.mts={sessions:Array.isArray(v?.sessions)?v.sessions:[],messages:Array.isArray(v?.messages)?v.messages:[]};queueStandaloneSave();}
  function mtsUid(prefix='MTS'){return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;}
  function mtsDurationHours(a,b){const x=new Date(a).getTime(),y=new Date(b).getTime();return Number.isFinite(x)&&Number.isFinite(y)&&y>x?Math.round(((y-x)/3600000)*1000000)/1000000:0;}
  function legacyHoursClient(r){const h=mtsDurationHours(r.clockInTimestamp,r.clockOutTimestamp);if(h)return h;const str=String(r.totalHours||'').toLowerCase(),n=parseFloat(str);if(!Number.isFinite(n))return 0;if(str.includes('min'))return n/60;if(str.includes('sec'))return n/3600;return n;}
  function legacyIsoClient(date,time,timestamp){if(timestamp&&Number.isFinite(Number(timestamp)))return new Date(Number(timestamp)).toISOString();const d=date||new Date().toISOString().slice(0,10);if(!time)return new Date(`${d}T08:00:00`).toISOString();const p=new Date(`${d} ${time}`);return Number.isNaN(p.getTime())?new Date(`${d}T08:00:00`).toISOString():p.toISOString();}
