  function formatDateTime(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):d.toLocaleString([], {dateStyle:'medium',timeStyle:'short'});}
  function formatTime(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});}
