  async function runOneJivanBackgroundTask(task){
    const id=String(task?.id||'');if(!id)return;
    window.dispatchEvent(new CustomEvent('assurance-regent-jivan-task-progress',{detail:{task,status:'RUNNING'}}));
    try{
      const ctx=agentPageContext();ctx.background={delegated:true,task_id:id};ctx.ui={fields:[],controls:[]};
      const studioSteps=developerStudioAllowed()?Math.max(8,Math.min(30,Number(jivanStudioConfig()?.runtime?.maxToolSteps||20))):10;const maxSteps=controlUser()?.role==='Developer'?Math.min(20,studioSteps):controlUser()?.role==='Administrator'?8:6;let data=null,lastResults=[],allResults=[],step=0;
      do{
        data=await supabaseFunction('recovery-agent',{mode:'background_task',task_id:id,message:String(task.instruction||''),page_context:ctx,continuation:step>0,continuation_step:step,action_results:lastResults.map(x=>{const y={...x};if(y.download)y.download={name:y.download.name,format:y.download.format,rows:y.download.rows};return y;})});
        lastResults=await executeJivanBackgroundActions(data?.ui_actions||[]);allResults.push(...lastResults);step++;
        if(!data?.continue_task||!lastResults.some(x=>x.ok)||step>=maxSteps)break;
        await agentDelay(120);
      }while(true);
      const blocked=allResults.filter(x=>!x.ok),downloads=allResults.filter(x=>x.ok&&x.download).map(x=>x.download);downloads.forEach(addAgentDownload);
      const base=String(data?.output_text||'Jivan completed the delegated task.').trim(),limitNote=data?.continue_task&&step>=maxSteps?` Background execution reached its ${maxSteps}-step safety limit.`:'',blockedText=blocked.length?` ${blocked.map(x=>x.error).join(' ')}`:'';
      const finalText=`${base}${limitNote}${blockedText}`.trim(),status=(blocked.length||Boolean(data?.continue_task&&step>=maxSteps))?'WAITING_USER':'COMPLETED';
      await supabaseRpc('assurance_regent_browser_agent_task_finish',{p_token:browserSessionToken,p_task_id:id,p_status:status,p_result_text:finalText,p_result_metadata:{steps:step,action_results:allResults.map(x=>({ok:x.ok,type:x.type,error:x.error||'',download:x.download?{name:x.download.name,format:x.download.format}:null})),downloads:downloads.map(x=>({name:x.name,format:x.format}))}});
      if(status==='WAITING_USER')toast('Jivan background task is waiting for your input. Open Background tasks for details.');else if(status==='COMPLETED')toast('Jivan completed a background task. Open Background tasks to review it.');
      await agentGovernanceAudit('background_task',id,status,finalText.slice(0,1200),{title:task.title||'',actions:allResults.length,steps:step});
      window.dispatchEvent(new CustomEvent('assurance-regent-jivan-task-progress',{detail:{task:{...task,status,result_text:finalText},status}}));
    }catch(err){const msg=err?.message||String(err);try{await supabaseRpc('assurance_regent_browser_agent_task_finish',{p_token:browserSessionToken,p_task_id:id,p_status:'FAILED',p_result_text:msg,p_result_metadata:{}});}catch{}toast(`Jivan background task failed: ${msg}`);await agentGovernanceAudit('background_task',id,'FAILED',msg,{});}
    await loadJivanTasks();
  }
