  async function exportData(kind){let rows=[];if(kind==='monthly'||kind==='engine')rows=engine.monthlyEngine();if(kind==='projects')rows=engine.state.projects;if(kind==='employees')rows=engine.state.employees;if(kind==='vacancies')rows=engine.state.vacancies;if(kind==='candidates')rows=engine.state.candidates;if(kind==='onboarding')rows=engine.state.onboarding;if(!rows.length)return toast('No live records are available to export.');const headers=Object.keys(rows[0]);const csv=[headers.join(','),...rows.map(r=>headers.map(h=>`"${String(r[h]??'').replaceAll('"','""')}"`).join(','))].join('\n'),name=`adra-${kind}.csv`,blob=new Blob([csv],{type:'text/csv'});try{await uploadPersistentBlob(blob,name,{category:'data-exports',entityType:'data-export',entityId:kind});}catch(err){return toast(err.message||'Could not persist export.');}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href);}
  function toast(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600);}
  function debounce(fn,ms){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms);};}

  /* Dependency-free canvas charts */
  function prepCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(500,rect.width*dpr);canvas.height=280*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);return {c,w:canvas.width/dpr,h:280};}
  function drawEmptyChart(canvas,message='Waiting for live data'){if(!canvas)return;const {c,w,h}=prepCanvas(canvas);c.clearRect(0,0,w,h);c.save();c.fillStyle='#71808a';c.textAlign='center';c.textBaseline='middle';c.font='600 14px Inter, system-ui, sans-serif';c.fillText(message,w/2,h/2);c.restore();}
  function axes(c,w,h,pad,min,max,labels,suffix=''){c.clearRect(0,0,w,h);c.strokeStyle='#e3ecef';c.fillStyle='#78909b';c.lineWidth=1;c.font='9px system-ui';for(let i=0;i<=4;i++){const y=pad.t+(h-pad.t-pad.b)*(i/4);c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();const v=max-(max-min)*(i/4);c.fillText(`${compact(v)}${suffix}`,4,y+3);}labels.forEach((x,i)=>{const cx=pad.l+(w-pad.l-pad.r)*(labels.length===1?.5:i/(labels.length-1||1));c.fillText(x,cx-16,h-8);});}
  function compact(v){const a=Math.abs(v);if(a>=1e6)return `${(v/1e6).toFixed(1)}m`;if(a>=1e3)return `${(v/1e3).toFixed(0)}k`;return `${Math.round(v)}`;}
  function drawLines(canvas,labels,series,opt={}){if(!canvas)return;const {c,w,h}=prepCanvas(canvas),pad={l:45,r:14,t:28,b:30};let vals=series.flatMap(s=>s.values).filter(Number.isFinite),min=opt.min??Math.min(0,...vals),max=opt.max??Math.max(...vals);if(max===min)max=min+1;axes(c,w,h,pad,min,max,labels,opt.suffix||'');series.forEach(s=>{c.strokeStyle=s.color;c.fillStyle=s.color;c.lineWidth=2.3;c.beginPath();s.values.forEach((v,i)=>{const x=pad.l+(w-pad.l-pad.r)*(i/(labels.length-1||1)),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();s.values.forEach((v,i)=>{const x=pad.l+(w-pad.l-pad.r)*(i/(labels.length-1||1)),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.fill();});});drawLegend(c,series,w);}
  function drawGroupedBars(canvas,labels,series,opt={}){if(!canvas)return;const vals=series.flatMap(s=>s.values).filter(Number.isFinite);if(!labels.length||!vals.length)return drawEmptyChart(canvas,'Waiting for live data');const {c,w,h}=prepCanvas(canvas),pad={l:50,r:14,t:32,b:32};let min=Math.min(0,...vals),max=Math.max(...vals);if(max===min)max=min+1;axes(c,w,h,pad,min,max,labels);const area=w-pad.l-pad.r,group=area/labels.length,bw=Math.max(3,Math.min(18,(group-12)/series.length));series.forEach((s,si)=>{c.fillStyle=s.color;s.values.forEach((v,i)=>{const zero=pad.t+(max)/(max-min)*(h-pad.t-pad.b),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b),x=pad.l+i*group+group/2-(series.length*bw)/2+si*bw;c.fillRect(x,Math.min(y,zero),bw-2,Math.abs(zero-y));});});drawLegend(c,series,w);}
  function drawHorizontalBars(canvas,labels,values,color,opt={}){if(!canvas)return;const hasPeople=Array.isArray(opt.people)&&opt.people.length>0,{c,w,h}=prepCanvas(canvas),pad={l:hasPeople?128:95,r:35,t:24,b:18};c.clearRect(0,0,w,h);const min=Math.min(0,...values),max=Math.max(0,...values),range=(max-min)||1,barH=Math.min(18,(h-pad.t-pad.b)/Math.max(labels.length,1)-5);c.font='9px system-ui';labels.forEach((lab,i)=>{const y=pad.t+i*((h-pad.t-pad.b)/labels.length),person=hasPeople?opt.people[i]:null,photo=safeProfilePhoto(person?.profilePhoto),textX=hasPeople?29:5;c.fillStyle='#637b87';c.fillText(lab,textX,y+barH*.75);if(hasPeople){c.save();c.beginPath();c.arc(14,y+barH/2,9,0,Math.PI*2);c.clip();c.fillStyle='#d7edf5';c.fillRect(5,y+barH/2-9,18,18);c.restore();if(photo){const img=new Image();img.onload=()=>{c.save();c.beginPath();c.arc(14,y+barH/2,9,0,Math.PI*2);c.clip();c.drawImage(img,5,y+barH/2-9,18,18);c.restore();};img.src=photo;}else{c.fillStyle='#385d6d';c.font='bold 6px system-ui';c.textAlign='center';c.fillText(companyInitials(lab),14,y+barH/2+2);c.textAlign='start';c.font='9px system-ui';}}const zero=pad.l+(-min/range)*(w-pad.l-pad.r),x=pad.l+((values[i]-min)/range)*(w-pad.l-pad.r);c.strokeStyle='#e4ecef';c.beginPath();c.moveTo(pad.l,y+barH+4);c.lineTo(w-pad.r,y+barH+4);c.stroke();c.fillStyle=color;c.fillRect(Math.min(zero,x),y,Math.max(2,Math.abs(x-zero)),barH);c.fillStyle='#425b67';c.fillText(num(values[i],1),Math.min(w-pad.r-25,Math.max(zero,x)+5),y+barH*.75);});}
  function drawLegend(c,series,w){let x=w-12;[...series].reverse().forEach(s=>{const tw=c.measureText(s.label).width;x-=tw+22;c.fillStyle=s.color;c.fillRect(x,8,8,8);c.fillStyle='#637b87';c.fillText(s.label,x+12,15);x-=8;});}

